let ai_output;
try {
  const raw = $json.choices?.[0]?.message?.content || $json.output?.[0]?.content?.[0]?.text || $json.message?.content || $json.text || $json.content || $json.output;
  ai_output = typeof raw === "string" ? JSON.parse(raw.replace(/^\s*```(?:json)?\s*/i, "").replace(/\s*```\s*$/, "").trim()) : raw;
} catch (e) {
  return { valid: false, errors: ["Invalid JSON from AI"], messageId: $('Fetch full email').item.json.messageId };
}

const errors = [];

if (!["risk", "growth", "routine"].includes(ai_output.signalType)) errors.push("signalType invalid");
if (!["positive", "neutral", "negative"].includes(ai_output.sentiment)) errors.push("sentiment invalid");
if (!["low", "medium", "high"].includes(ai_output.urgency)) errors.push("urgency invalid");

const limits = { topic: 100, summary: 500, evidence: 300, classifier: 100, proposedAction: 700, proposedRationale: 500, proposedResponse: 1500 };
for (const [field, max] of Object.entries(limits)) {
  const val = (ai_output[field] || "").toString().trim();
  if (val.length > max) errors.push(`${field} too long`);
}

if (["risk", "growth"].includes(ai_output.signalType)) {
  if (!ai_output.proposedAction || ai_output.proposedAction.trim().length === 0) errors.push("proposedAction required");
  if (!ai_output.proposedRationale || ai_output.proposedRationale.trim().length === 0) errors.push("proposedRationale required");
  if (!ai_output.proposedResponse || ai_output.proposedResponse.trim().length === 0) errors.push("proposedResponse required");
}

const messageId = $('Fetch full email').item.json.messageId;
const senderEmail = $('Fetch full email').item.json.senderEmail;

if (errors.length > 0) return { valid: false, errors, messageId };

return {
  valid: true,
  payload: ai_output,
  messageId: messageId,
  senderEmail: senderEmail
};

const response = $json.body || $json;
return {
  status: "success",
  signalId: response.signalId,
  matchStatus: response.matchStatus,
  accountId: response.accountId || null,
  duplicate: response.duplicate === true
};

// Anti-loop: our own internal approval notification must never be re-ingested as a customer signal.
const incomingSubject = $json.Subject || $json.subject || "";
if (incomingSubject.startsWith("[Action approved]")) return [];

const messageId = $json.id;

const fromField = $json.From || $json.from;
let senderEmail = "unknown";
if (typeof fromField === "string") {
  const m = fromField.match(/([a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,})/i);
  senderEmail = m ? m[1] : fromField;
} else if (fromField && fromField.value && fromField.value[0]) {
  senderEmail = fromField.value[0].address;
}

const subject = $json.Subject || $json.subject || "(no subject)";
const body = $json.text || $json.snippet || $json.html || "(no body)";

const systemPrompt = `You are a customer signal classifier. Classify this email as risk, growth, or routine.

Return ONLY valid JSON:
- topic (1-100 chars)
- signalType ("risk"|"growth"|"routine")
- sentiment ("positive"|"neutral"|"negative")
- urgency ("low"|"medium"|"high")
- summary (1-500 chars)
- evidence (1-300 chars, quote from email)
- classifier ("gpt-5-mini-signal-classifier")
- proposedAction (required if risk/growth, else null)
- proposedRationale (required if risk/growth, else null)
- proposedResponse (required if risk/growth, else null; 1-1500 chars, a ready-to-send reply to the customer acknowledging their message and the planned next step - this is a DRAFT a human reviews and edits before it is ever sent, never send anything yourself)

NO explanations, ONLY JSON.`;

const userPrompt = `From: ${senderEmail}
Subject: ${subject}

Body:
${body}

Classify this. Return JSON only.`;

return {
  system: systemPrompt,
  user: userPrompt,
  maxTokens: 1500,
  messageId: messageId,
  senderEmail: senderEmail,
  timestamp: new Date().toISOString()
};

