={{ (() => {
  const p = $json.payload;
  const body = {
    messageId: $('Guard and build AI prompt').item.json.messageId,
    senderEmail: $('Guard and build AI prompt').item.json.senderEmail,
    topic: p.topic,
    signalType: p.signalType,
    sentiment: p.sentiment,
    urgency: p.urgency,
    summary: p.summary,
    evidence: p.evidence,
    classifier: p.classifier,
  };
  if (["risk","growth"].includes(p.signalType)) {
    body.proposedAction = p.proposedAction;
    body.proposedRationale = p.proposedRationale;
    body.proposedResponse = p.proposedResponse;
  }
  return body;
})() }}
